CREATE TABLE test_suites (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name VARCHAR(160) NOT NULL, description VARCHAR(1000), module VARCHAR(80), enabled BOOLEAN DEFAULT TRUE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE test_cases (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, case_id VARCHAR(80) NOT NULL UNIQUE, name VARCHAR(160) NOT NULL, module VARCHAR(80), description VARCHAR(1000), preconditions VARCHAR(1000), test_steps VARCHAR(4000), expected_result VARCHAR(1000), priority VARCHAR(20), test_type VARCHAR(30), automation_status VARCHAR(30), suite_id BIGINT REFERENCES test_suites(id));
CREATE TABLE test_executions (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, suite_id BIGINT REFERENCES test_suites(id), suite_name VARCHAR(160), environment VARCHAR(30), browser VARCHAR(30), mode VARCHAR(30), status VARCHAR(30), total_tests INT DEFAULT 0, passed_tests INT DEFAULT 0, failed_tests INT DEFAULT 0, skipped_tests INT DEFAULT 0, current_test VARCHAR(160), started_at TIMESTAMP, finished_at TIMESTAMP, duration_ms BIGINT DEFAULT 0);
CREATE TABLE test_results (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, execution_id BIGINT REFERENCES test_executions(id), case_id VARCHAR(80), test_name VARCHAR(160), module VARCHAR(80), status VARCHAR(30), duration_ms BIGINT DEFAULT 0, error_message VARCHAR(4000), screenshot_path VARCHAR(500), logs VARCHAR(8000));
CREATE TABLE test_activities (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, type VARCHAR(50), title VARCHAR(160), description VARCHAR(1000), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE employees (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, employee_id VARCHAR(30) UNIQUE, first_name VARCHAR(80), last_name VARCHAR(80), email VARCHAR(160), phone VARCHAR(30), department VARCHAR(80), job_title VARCHAR(120), joining_date DATE, status VARCHAR(30));
CREATE TABLE leave_requests (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, employee_id VARCHAR(30), employee_name VARCHAR(160), leave_type VARCHAR(50), start_date DATE, end_date DATE, reason VARCHAR(1000), status VARCHAR(30));
CREATE TABLE candidates (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, first_name VARCHAR(80), last_name VARCHAR(80), email VARCHAR(160), position VARCHAR(160), status VARCHAR(50));



